export const TOOLS = {
  '/tools/pdf-check/': { es: ['Comprobación de PDF', 'Cada guardado dentro de un contrato o reserva en PDF, qué cambió, si las firmas siguen cubriendo el archivo y dónde no cuadran metadatos y fuentes.'], de: ['PDF-Prüfung', 'Jede Speicherung in einem Vertrags- oder Reservierungs-PDF, was sie änderte, ob Signaturen die Datei noch decken und wo Metadaten und Schriften abweichen.'], fr: ['Vérification de PDF', 'Chaque enregistrement dans un PDF de contrat ou de réservation, ce qu’il a changé, si les signatures couvrent encore le fichier et où métadonnées et polices divergent.'], nl: ['Pdf-controle', 'Elke opslag in een contract- of reserverings-pdf, wat die veranderde, of handtekeningen het bestand nog dekken en waar metadata en lettertypen verschillen.'], ru: ['Проверка PDF', 'Каждое сохранение в PDF договора или брони, что оно изменило, покрывают ли подписи файл и где расходятся метаданные и шрифты.'], zh: ['PDF 检查', '合同或预订 PDF 中的每次保存、改动了什么、签名是否仍覆盖整个文件，以及元数据与字体不一致之处。'], ar: ['فحص PDF', 'كل حفظ داخل ملف PDF لعقد أو حجز، وما غيّره، وهل ما زالت التواقيع تغطي الملف، وأين تختلف البيانات الوصفية والخطوط.'] },
  '/tools/image-check/': { es: ['Comprobación de imagen', '¿Sale este render en la página de otro proyecto? Una huella perceptual comparada con las imágenes de todos los proyectos que seguimos.'], de: ['Bildprüfung', 'Erscheint dieses Rendering auf der Seite eines anderen Projekts? Ein Wahrnehmungs-Fingerabdruck, verglichen mit den Bildern aller verfolgten Projekte.'], fr: ['Vérification d’image', 'Ce rendu figure-t-il sur la page d’un autre projet ? Une empreinte perceptuelle comparée aux images de tous les projets suivis.'], nl: ['Beeldcontrole', 'Staat deze render op de pagina van een ander project? Een perceptuele vingerafdruk vergeleken met de beelden van alle gevolgde projecten.'], ru: ['Проверка изображения', 'Есть ли этот рендер на странице другого проекта? Перцептивный отпечаток сравнивается с изображениями всех отслеживаемых проектов.'], zh: ['图片检查', '这张效果图是否出现在其他项目的页面上？将感知指纹与我们跟踪的所有项目图片比对。'], ar: ['فحص الصورة', 'هل تظهر هذه الصورة في صفحة مشروع آخر؟ بصمة إدراكية تُقارن بصور كل المشاريع التي نتابعها.'] },
  '/tools/payment-email-check/': { es: ['Comprobación de email de pago', 'Pega un email que te pide pagar: Reply-To y dominios parecidos frente a las webs de promotores, SPF, DKIM y DMARC, edad del dominio y cambios de cuenta.'], de: ['Zahlungs-E-Mail-Prüfung', 'E-Mail mit Zahlungsaufforderung einfügen: Reply-To und ähnliche Domains gegen Bauträger-Websites, SPF, DKIM und DMARC, Domainalter, geänderte Bankdaten.'], fr: ['Vérification d’email de paiement', 'Collez un email qui demande un paiement : Reply-To et domaines similaires face aux sites des promoteurs, SPF, DKIM et DMARC, âge du domaine, changement de RIB.'], nl: ['Controle van betaalmail', 'Plak een mail die om betaling vraagt: Reply-To en lijkende domeinen tegen sites van ontwikkelaars, SPF, DKIM en DMARC, domeinleeftijd, gewijzigde bankgegevens.'], ru: ['Проверка письма об оплате', 'Вставьте письмо с просьбой оплатить: Reply-To и похожие домены против сайтов застройщиков, SPF, DKIM и DMARC, возраст домена, смена реквизитов.'], zh: ['付款邮件检查', '粘贴要求你付款的邮件：Reply-To 与相似域名对照开发商网站、SPF、DKIM 和 DMARC 结果、域名年龄、更改银行信息的措辞。'], ar: ['فحص بريد الدفع', 'الصق رسالة تطلب منك الدفع: Reply-To والنطاقات المشابهة مقابل مواقع المطوّرين، ونتائج SPF وDKIM وDMARC، وعمر النطاق، وتغيير بيانات البنك.'] },
  '/tools/account-check/': { es: ['Comprobación de cuenta', 'Dígito de control, longitud y banco del IBAN, formato SWIFT/BIC, nombre registrado del banco en GLEIF, país de la cuenta y reglas de escrow de Dubái.'], de: ['Kontoprüfung', 'IBAN-Prüfziffer, Länge und Bankcode, SWIFT/BIC-Format, eingetragener Bankname bei GLEIF, Kontoland und Treuhandregeln in Dubai.'], fr: ['Vérification de compte', 'Clé, longueur et code banque de l’IBAN, format SWIFT/BIC, nom enregistré de la banque chez GLEIF, pays du compte et règles d’escrow de Dubaï.'], nl: ['Rekeningcontrole', 'IBAN-controlecijfer, lengte en bankcode, SWIFT/BIC-formaat, geregistreerde banknaam bij GLEIF, land van de rekening en escrowregels in Dubai.'], ru: ['Проверка счёта', 'Контрольная сумма, длина и код банка IBAN, формат SWIFT/BIC, зарегистрированное имя банка в GLEIF, страна счёта и правила эскроу в Дубае.'], zh: ['账户检查', 'IBAN 校验位、长度和银行代码，SWIFT/BIC 格式，GLEIF 中银行的注册名称，账户国家，以及迪拜托管账户规则。'], ar: ['فحص الحساب', 'رقم التحقق وطول IBAN ورمز البنك، وصيغة SWIFT/BIC، واسم البنك المسجّل لدى GLEIF، وبلد الحساب، وقواعد حساب الضمان في دبي.'] },
  '/tools/contract-check/': { es: ['Revisión de contrato con IA en tu dispositivo', 'Suelta el PDF: partes, precio, pagos, entrega, penalización, reembolso, escrow, título y ley aplicable, cada uno con la cita exacta de tu archivo.'], de: ['Vertragsprüfung mit KI auf dem Gerät', 'PDF ablegen: Parteien, Preis, Zahlungen, Fertigstellung, Verzugsstrafe, Erstattung, Treuhand, Titel und Recht, jeweils mit dem genauen Zitat aus Ihrer Datei.'], fr: ['Contrôle du contrat par IA sur l’appareil', 'Déposez le PDF : parties, prix, paiements, livraison, pénalité, remboursement, escrow, titre et droit applicable, chacun avec la citation exacte de votre fichier.'], nl: ['Contractcontrole met AI op je apparaat', 'Zet de pdf neer: partijen, prijs, betalingen, oplevering, boete, terugbetaling, escrow, titel en toepasselijk recht, elk met het exacte citaat uit je bestand.'], ru: ['Проверка договора ИИ на устройстве', 'Перетащите PDF: стороны, цена, платежи, сдача, неустойка, возврат, эскроу, право собственности и применимое право, с точной цитатой из файла.'], zh: ['设备端 AI 合同检查', '拖入合同 PDF：当事方、价格、付款、交付、延期罚金、退款、托管、产权和适用法律，每项附文件中的原文引文。'], ar: ['فحص العقد بذكاء اصطناعي على جهازك', 'أفلت ملف PDF: الأطراف والسعر والدفعات والتسليم وغرامة التأخير والاسترداد والضمان والملكية والقانون الحاكم، كل منها باقتباس دقيق من ملفك.'] },
  '/tools/contract-reader/': { es: ['Lector de contratos y folletos', 'Suelta un contrato o folleto en PDF en 13 idiomas: reglas fijas marcan entrega, penalización, escrow, calendario de pagos, ley aplicable y cancelación, con número de página.'], de: ['Vertrags- und Prospektleser', 'Vertrag oder Prospekt als PDF in 13 Sprachen: feste Regeln markieren Übergabe, Verzugsstrafe, Treuhand, Zahlungsplan, Recht und Rücktritt, mit Seitenzahl.'], fr: ['Lecteur de contrats et brochures', 'Contrat ou brochure en PDF dans 13 langues : des règles fixes repèrent livraison, pénalité, escrow, échéancier, droit applicable et annulation, avec la page.'], nl: ['Lezer voor contracten en brochures', 'Contract of brochure als pdf in 13 talen: vaste regels markeren oplevering, boete, escrow, betaalschema, toepasselijk recht en annulering, met paginanummer.'], ru: ['Чтение договоров и брошюр', 'Договор или брошюра в PDF на 13 языках: фиксированные правила отмечают сдачу, неустойку, эскроу, график платежей, право и расторжение, с номером страницы.'], zh: ['合同与宣传册阅读器', '拖入 13 种语言之一的合同或宣传册 PDF：固定规则标出交付日期、延期罚金、托管、付款计划、适用法律和解约条款，并注明页码。'], ar: ['قارئ العقود والكتيبات', 'أفلت عقداً أو كتيباً بصيغة PDF بإحدى 13 لغة: تحدد قواعد ثابتة موعد التسليم وغرامة التأخير والضمان وجدول الدفع والقانون والإلغاء، مع رقم الصفحة.'] },
  '/tools/permit-photo/': { es: ['Lector de fotos de permisos', 'Foto de un permiso, licencia o certificado de empresa: leemos el texto en tu dispositivo, encontramos números de registro y los consultas con un toque.'], de: ['Genehmigungsfoto-Leser', 'Foto einer Genehmigung, Lizenz oder Firmenurkunde: Text auf Ihrem Gerät gelesen, Registernummern gefunden und mit einem Tipp nachgeschlagen.'], fr: ['Lecteur de photo de permis', 'Photo d’un permis, d’une licence ou d’un certificat de société : le texte est lu sur votre appareil, les numéros de registre trouvés et vérifiables d’un geste.'], nl: ['Lezer voor vergunningsfoto’s', 'Foto van een vergunning, licentie of bedrijfscertificaat: we lezen de tekst op je apparaat, vinden registernummers en zoeken er één op met één tik.'], ru: ['Чтение фото разрешения', 'Фото разрешения, лицензии или свидетельства компании: текст читается на устройстве, номера реестров находятся и проверяются одним касанием.'], zh: ['许可证照片识别', '许可证、执照或公司证书的照片：在你的设备上识别文字，找到登记编号，一键查询。'], ar: ['قارئ صور التراخيص', 'صورة ترخيص أو رخصة أو شهادة شركة: نقرأ النص على جهازك، ونجد أرقام السجلات، وتبحث عن أحدها بلمسة واحدة.'] },
  '/tools/permit-check/': { es: ['Comprobación del QR del permiso', 'Foto de un permiso PBG, un anuncio de Dubái o un título: leemos el código QR y te decimos si el enlace es de la agencia oficial.'], de: ['QR-Prüfung der Genehmigung', 'Foto einer PBG-Genehmigung, einer Dubai-Anzeige oder eines Titels: wir lesen den QR-Code und sagen, ob der Link zur offiziellen Behörde gehört.'], fr: ['Vérification du QR du permis', 'Photo d’un permis PBG, d’une annonce à Dubaï ou d’un titre : nous lisons le QR code et disons si le lien appartient à l’agence officielle.'], nl: ['QR-controle van de vergunning', 'Foto van een PBG-vergunning, Dubai-advertentie of titel: we lezen de QR-code en zeggen of de link bij de officiële instantie hoort.'], ru: ['Проверка QR разрешения', 'Фото разрешения PBG, объявления в Дубае или документа о праве: читаем QR-код и говорим, ведёт ли ссылка на официальное ведомство.'], zh: ['许可证二维码检查', 'PBG 许可证、迪拜广告或产权文件的照片：我们读取二维码，告诉你链接是否属于官方机构。'], ar: ['فحص رمز QR للترخيص', 'صورة ترخيص PBG أو إعلان في دبي أو سند ملكية: نقرأ رمز QR ونخبرك إن كان الرابط تابعاً للجهة الرسمية.'] },
  '/tools/site-visit/': { es: ['Registro de visita a obra', 'En el proyecto: tu GPS y fotos frente a la ubicación del solar en nuestros datos, firmado y fechado por Kolaboro. Solo se envían huellas de las fotos.'], de: ['Baustellenbesuch-Protokoll', 'Am Projekt: Ihr GPS und Ihre Fotos gegen die Grundstückslage in unseren Daten, von Kolaboro signiert und datiert. Nur Foto-Fingerabdrücke werden gesendet.'], fr: ['Relevé de visite de chantier', 'Sur place : votre GPS et vos photos comparés à l’emplacement du terrain dans nos données, signés et horodatés par Kolaboro. Seules les empreintes des photos sont envoyées.'], nl: ['Verslag van een bouwplaatsbezoek', 'Bij het project: je gps en foto’s tegen de kavellocatie in onze data, ondertekend en gedateerd door Kolaboro. Alleen vingerafdrukken van foto’s worden verstuurd.'], ru: ['Запись визита на стройку', 'На объекте: ваш GPS и фото сравниваются с участком в наших данных, подпись и метка времени Kolaboro. Отправляются только отпечатки фото.'], zh: ['工地访问记录', '在项目现场：将你的 GPS 和照片与我们记录中的地块位置对照，由 Kolaboro 签名并加时间戳。只发送照片指纹。'], ar: ['سجل زيارة الموقع', 'في المشروع: موقعك عبر GPS وصورك مقارنة بموقع القطعة في سجلاتنا، موقّعة ومؤرّخة من Kolaboro. تُرسل بصمات الصور فقط.'] },
  '/tools/law/': { es: ['Notas legales', 'Propiedad de extranjeros, escrow y depósitos en Indonesia, Dubái, Tailandia, España y Portugal, con el artículo oficial citado y enlazado.'], de: ['Rechtsnotizen', 'Ausländereigentum, Treuhand und Anzahlungsregeln in Indonesien, Dubai, Thailand, Spanien und Portugal, mit zitiertem und verlinktem Gesetzesartikel.'], fr: ['Notes juridiques', 'Propriété des étrangers, escrow et acomptes en Indonésie, à Dubaï, en Thaïlande, en Espagne et au Portugal, avec l’article officiel cité et lié.'], nl: ['Juridische notities', 'Eigendom voor buitenlanders, escrow en aanbetalingen in Indonesië, Dubai, Thailand, Spanje en Portugal, met het officiële artikel geciteerd en gelinkt.'], ru: ['Правовые заметки', 'Собственность иностранцев, эскроу и задатки в Индонезии, Дубае, Таиланде, Испании и Португалии, с цитатой и ссылкой на официальную статью.'], zh: ['法律要点', '印尼、迪拜、泰国、西班牙和葡萄牙的外国人产权、托管和定金规则，引用并链接官方条文。'], ar: ['ملاحظات قانونية', 'تملّك الأجانب والضمان وقواعد الدفعات في إندونيسيا ودبي وتايلاند وإسبانيا والبرتغال، مع اقتباس المادة الرسمية ورابطها.'] },
  '/tools/contract-addendum/': { es: ['Generador de anexos al contrato', 'Cláusulas de protección para proponer al promotor en 9 mercados, cada una con su artículo de ley, en PDF o Word. Un borrador para tu abogado, no asesoría legal.'], de: ['Vertragszusatz-Generator', 'Schutzklauseln für den Bauträger in 9 Märkten, jede mit ihrem Gesetzesartikel, als PDF oder Word. Ein Entwurf für Ihren Anwalt, keine Rechtsberatung.'], fr: ['Générateur d’avenant', 'Clauses protectrices à proposer au promoteur dans 9 marchés, chacune avec son article de loi, en PDF ou Word. Un brouillon pour votre avocat, pas un conseil juridique.'], nl: ['Bouwer van contractaanvullingen', 'Beschermende clausules voor de ontwikkelaar in 9 markten, elk met het wetsartikel, als pdf of Word. Een concept voor je advocaat, geen juridisch advies.'], ru: ['Конструктор допсоглашения', 'Защитные пункты для застройщика на 9 рынках, каждый со статьёй закона, в PDF или Word. Черновик для вашего юриста, не юридическая консультация.'], zh: ['合同补充条款生成器', '9 个市场中可向开发商提出的保护条款，每条附所依据的法律条文，可导出 PDF 或 Word。供律师参考的草稿，不是法律意见。'], ar: ['منشئ ملحق العقد', 'بنود حماية تقترحها على المطوّر في 9 أسواق، لكل منها المادة القانونية التي تستند إليها، بصيغة PDF أو Word. مسودة لمحاميك، لا استشارة قانونية.'] },
  '/tools/bulk-check/': { es: ['Comprobación en bloque para agentes y prestamistas', 'Pega o sube hasta 100 proyectos, promotores o enlaces, cotejados en tu dispositivo con nuestro índice público. Exporta CSV.'], de: ['Sammelprüfung für Makler und Kreditgeber', 'Bis zu 100 Projekte, Bauträger oder Links einfügen oder hochladen, auf Ihrem Gerät mit unserem öffentlichen Index abgeglichen. CSV-Export.'], fr: ['Vérification en masse pour agents et prêteurs', 'Collez ou envoyez jusqu’à 100 projets, promoteurs ou liens, comparés sur votre appareil à notre index public. Export CSV.'], nl: ['Bulkcontrole voor makelaars en kredietverstrekkers', 'Plak of upload tot 100 projecten, ontwikkelaars of links, op je apparaat vergeleken met onze openbare index. Export als csv.'], ru: ['Массовая проверка для агентов и кредиторов', 'Вставьте или загрузите до 100 проектов, застройщиков или ссылок, сверка на вашем устройстве с нашим открытым индексом. Экспорт CSV.'], zh: ['面向中介和贷款机构的批量检查', '粘贴或上传最多 100 个项目、开发商或链接，在你的设备上与我们的公开索引比对。可导出 CSV。'], ar: ['فحص جماعي للوكلاء والمقرضين', 'الصق أو ارفع حتى 100 مشروع أو مطوّر أو رابط، تُطابق على جهازك مع فهرسنا العام. تصدير CSV.'] },
  '/tools/contract-scan/': { es: ['Primera lectura del contrato', 'Pega el texto del contrato para ver qué protecciones del comprador tiene o le faltan. Para una lectura cláusula a cláusula del PDF, usa la revisión de contrato.'], de: ['Erster Vertragsdurchgang', 'Vertragstext einfügen und sehen, welche Käuferschutzklauseln vorhanden sind oder fehlen. Für die Klausel-für-Klausel-Lesung des PDF die Vertragsprüfung nutzen.'], fr: ['Première lecture du contrat', 'Collez le texte du contrat pour voir les protections de l’acheteur présentes ou absentes. Pour une lecture clause par clause du PDF, utilisez le contrôle du contrat.'], nl: ['Eerste lezing van het contract', 'Plak de contracttekst voor een lijst van koperbescherming die er is of ontbreekt. Voor een lezing per clausule van de pdf, gebruik de contractcontrole.'], ru: ['Первичный разбор договора', 'Вставьте текст договора и увидите, какие защиты покупателя есть или отсутствуют. Для разбора PDF по пунктам используйте проверку договора.'], zh: ['合同初步检查', '粘贴合同文本，快速列出已有或缺失的买家保护条款。如需逐条阅读 PDF 并附引文，请用合同检查。'], ar: ['قراءة أولى للعقد', 'الصق نص العقد لترى قائمة سريعة بحمايات المشتري الموجودة أو الناقصة. لقراءة PDF بنداً بنداً مع الاقتباسات استخدم فحص العقد.'] },
  '/tools/payment-risk/': { es: ['Riesgo del plan de pagos', 'Introduce el calendario de pagos: una nota de 0 a 100 y la curva del dinero en riesgo durante la obra.'], de: ['Risiko des Zahlungsplans', 'Zahlungsplan eingeben: eine Bewertung von 0 bis 100 und die Kurve des Geldes im Risiko über die Bauzeit.'], fr: ['Risque de l’échéancier', 'Saisissez l’échéancier : une note de 0 à 100 et la courbe de l’argent exposé pendant les travaux.'], nl: ['Risico van het betaalplan', 'Voer het betaalschema in: een score van 0 tot 100 en de curve van het geld in gevaar tijdens de bouw.'], ru: ['Риск графика платежей', 'Введите график платежей: оценка от 0 до 100 и кривая денег под риском на протяжении стройки.'], zh: ['付款计划风险评分', '输入付款计划：得到 0 到 100 的评分，以及施工期间资金风险曲线。'], ar: ['درجة مخاطر خطة الدفع', 'أدخل جدول الدفع: درجة من 0 إلى 100 ومنحنى المال المعرّض للخطر على مدى البناء.'] },
  '/tools/payment-plan/': { es: ['Comprobador del plan de pagos', 'Pega el plan tal cual: marca depósitos grandes, pagos por fecha en lugar de por fase de obra y falta de retención hasta la entrega.'], de: ['Zahlungsplan-Prüfer', 'Plan wie geschrieben einfügen: markiert hohe Anzahlungen, Zahlungen nach Datum statt Baufortschritt und fehlenden Einbehalt bis zur Übergabe.'], fr: ['Vérificateur d’échéancier', 'Collez le plan tel quel : signale les gros acomptes, les paiements à date plutôt qu’à l’avancement et l’absence de retenue jusqu’à la livraison.'], nl: ['Controle van het betaalplan', 'Plak het plan zoals het is: markeert grote aanbetalingen, betalingen op datum in plaats van bouwfase en geen inhouding tot oplevering.'], ru: ['Проверка графика платежей', 'Вставьте график как есть: отметим крупные задатки, платежи по датам вместо этапов стройки и отсутствие удержания до сдачи.'], zh: ['付款计划检查', '按原文粘贴计划：标出高额定金、按日期而非施工阶段付款，以及交付前无保留款。'], ar: ['فاحص خطة الدفع', 'الصق الخطة كما كُتبت: تُبرز الدفعات المقدمة الكبيرة، والدفع بالتواريخ بدل مراحل البناء، وغياب مبلغ محتجز حتى التسليم.'] },
  '/tools/risk/': { es: ['Calculadora de riesgo sobre plano', 'Solo precio y plazos: el dinero expuesto antes de la entrega y lo que te costaría un retraso de unos meses.'], de: ['Off-Plan-Risikorechner', 'Nur Preis und Termine: das vor der Übergabe gebundene Geld und was Sie eine Verzögerung um einige Monate kosten würde.'], fr: ['Calculateur de risque sur plan', 'Prix et délais seulement : l’argent exposé avant la livraison et ce que vous coûterait un retard de quelques mois.'], nl: ['Risicocalculator voor op plan', 'Alleen prijs en planning: het geld dat vóór oplevering vastzit en wat een vertraging van enkele maanden je kost.'], ru: ['Калькулятор риска новостройки', 'Только цена и сроки: деньги под риском до сдачи и во что обойдётся задержка на несколько месяцев.'], zh: ['期房风险计算器', '只看价格和时间：交付前暴露的资金，以及延期数月的成本。'], ar: ['حاسبة مخاطر الشراء على الخارطة', 'السعر والتوقيت فقط: المال المعرّض قبل التسليم وكم يكلّفك تأخير بضعة أشهر.'] },
  '/tools/currency-risk/': { es: ['Riesgo de divisa', 'Tu plan de pagos en tu moneda si el tipo de cambio se mueve un 10 % o un 20 %.'], de: ['Währungsrisiko', 'Ihr Zahlungsplan in Ihrer Heimatwährung, wenn sich der Kurs um 10 % oder 20 % bewegt.'], fr: ['Risque de change', 'Votre échéancier dans votre monnaie si le taux bouge de 10 % ou 20 %.'], nl: ['Valutarisico', 'Je betaalplan in je eigen munt als de koers 10% of 20% beweegt.'], ru: ['Валютный риск', 'Ваш график платежей в вашей валюте при изменении курса на 10 % или 20 %.'], zh: ['汇率风险', '汇率变动 10% 或 20% 时，以你本国货币计算的付款计划。'], ar: ['مخاطر العملة', 'خطة دفعك بعملة بلدك إذا تحرّك سعر الصرف 10% أو 20%.'] },
  '/tools/total-cost/': { es: ['Coste total de la compra', 'Impuestos de compra, honorarios, gastos de comunidad, financiación y alquiler.'], de: ['Gesamtkosten des Eigentums', 'Erwerbssteuern, Gebühren, Nebenkosten, Finanzierung und Miete.'], fr: ['Coût total de possession', 'Taxes d’achat, frais, charges, financement et loyer.'], nl: ['Totale kosten van bezit', 'Aankoopbelastingen, kosten, servicekosten, financiering en huur.'], ru: ['Полная стоимость владения', 'Налоги при покупке, сборы, обслуживание, финансирование и аренда.'], zh: ['持有总成本', '购置税、各项费用、物业费、融资和租金。'], ar: ['التكلفة الكاملة للتملّك', 'ضرائب الشراء والرسوم ورسوم الخدمة والتمويل والإيجار.'] },
  '/tools/yield-check/': { es: ['Comprobación de rentabilidad', 'La rentabilidad anunciada frente a la rentabilidad tras ocupación y gastos.'], de: ['Mietrendite-Prüfung', 'Die beworbene Rendite gegen die Rendite nach Auslastung und Kosten.'], fr: ['Vérification du rendement', 'Le rendement annoncé face au rendement après occupation et frais.'], nl: ['Controle van het huurrendement', 'Het geadverteerde rendement tegen het rendement na bezetting en kosten.'], ru: ['Проверка доходности', 'Заявленная доходность против доходности с учётом загрузки и расходов.'], zh: ['租金回报检查', '宣传的回报率与扣除入住率和成本后的回报率对比。'], ar: ['فحص العائد الإيجاري', 'العائد المعلن مقابل العائد بعد نسبة الإشغال والتكاليف.'] },
  '/tools/delay-compensation/': { es: ['Compensación por retraso', 'Según tu contrato: lo que paga tu cláusula de retraso, el tope y las preguntas que hacer.'], de: ['Entschädigung bei Verzug', 'Aus Ihrem Vertrag: was Ihre Verzugsklausel zahlt, die Obergrenze und die Fragen, die Sie stellen sollten.'], fr: ['Indemnité de retard', 'D’après votre contrat : ce que paie votre clause de retard, le plafond et les questions à poser.'], nl: ['Vergoeding bij late oplevering', 'Uit je eigen contract: wat je vertragingsclausule betaalt, het plafond en de vragen om te stellen.'], ru: ['Компенсация за задержку', 'По вашему договору: что платит пункт о задержке, предел и вопросы, которые стоит задать.'], zh: ['延期交付补偿', '依据你的合同：延期条款赔付多少、上限是多少，以及要问的问题。'], ar: ['تعويض التأخر في التسليم', 'من عقدك أنت: ما يدفعه بند التأخير، والحد الأقصى، والأسئلة التي تطرحها.'] },
  '/tools/late-handover/': { es: ['Entrega tardía: contrato y ley', 'Según la ley, no tu contrato: lo que te corresponde si la entrega se retrasa, citado del texto oficial de cada país.'], de: ['Verspätete Übergabe: Vertrag und Gesetz', 'Aus dem Gesetz, nicht Ihrem Vertrag: was Ihnen bei verspäteter Übergabe zusteht, zitiert aus dem amtlichen Text jedes Landes.'], fr: ['Livraison en retard : contrat et loi', 'D’après la loi, pas votre contrat : ce qui vous est dû en cas de retard, cité du texte officiel de chaque pays.'], nl: ['Late oplevering: contract en wet', 'Uit de wet, niet je contract: waar je recht op hebt bij late oplevering, geciteerd uit de officiële tekst per land.'], ru: ['Поздняя сдача: договор и закон', 'По закону, а не по договору: что вам положено при задержке сдачи, с цитатой официального текста каждой страны.'], zh: ['延期交付：合同与法律', '依据法律而非合同：交付延期时你应得什么，引用各国官方条文。'], ar: ['التسليم المتأخر: العقد والقانون', 'من القانون لا من عقدك: ما تستحقه عند تأخر التسليم، مقتبساً من النص الرسمي لكل بلد.'] },
  '/tools/build-cost/': { es: ['Precio por debajo del coste de obra', 'Tu precio por m² frente a los costes de construcción publicados para la ciudad. Una alerta es una pregunta, no una prueba.'], de: ['Preis unter Baukosten', 'Ihr Preis pro m² gegen veröffentlichte Baukosten der Stadt. Ein Hinweis ist eine Frage, kein Beweis.'], fr: ['Prix sous le coût de construction', 'Votre prix au m² face aux coûts de construction publiés pour la ville. Une alerte est une question, pas une preuve.'], nl: ['Prijs onder de bouwkosten', 'Je prijs per m² tegen gepubliceerde bouwkosten voor de stad. Een signaal is een vraag, geen bewijs.'], ru: ['Цена ниже стоимости стройки', 'Ваша цена за м² против опубликованных затрат на строительство в городе. Флажок это вопрос, а не доказательство.'], zh: ['低于建造成本的价格', '你的每平方米价格与该城市公布的建造成本区间对比。提示是要问的问题，不是证据。'], ar: ['سعر أقل من تكلفة البناء', 'سعرك للمتر المربع مقابل نطاقات تكلفة البناء المنشورة للمدينة. التنبيه سؤال تطرحه، لا دليل.'] },
  '/tools/resale-exit/': { es: ['Lista de salida por reventa', '¿Puedes vender antes de la entrega? Cesión, consentimiento, comisiones y permanencia.'], de: ['Checkliste Weiterverkauf', 'Können Sie vor der Übergabe verkaufen: Abtretung, Zustimmung, Gebühren und Sperrfrist.'], fr: ['Liste de sortie par revente', 'Pouvez-vous revendre avant la livraison : cession, accord, frais et durée de blocage.'], nl: ['Checklist doorverkoop', 'Kun je verkopen vóór oplevering: overdracht, toestemming, kosten en blokkering.'], ru: ['Чек-лист перепродажи', 'Можно ли продать до сдачи: переуступка, согласие, сборы и срок запрета.'], zh: ['转售退出清单', '交付前能否转售：转让、同意、费用和锁定期。'], ar: ['قائمة الخروج بإعادة البيع', 'هل يمكنك البيع قبل التسليم: التنازل والموافقة والرسوم وفترة الحظر.'] },
  '/tools/market-match/': { es: ['Mercado a tu medida', 'Ordena los mercados sobre plano con información pública según tu presupuesto y tus objetivos.'], de: ['Passender Markt', 'Off-Plan-Märkte nach öffentlichen Informationen für Ihr Budget und Ihre Ziele ordnen.'], fr: ['Marché adapté', 'Classez les marchés sur plan selon les informations publiques, votre budget et vos objectifs.'], nl: ['Passende markt', 'Rangschik markten op plan op openbare informatie voor je budget en doelen.'], ru: ['Подбор рынка', 'Ранжирование рынков новостроек по открытым данным под ваш бюджет и цели.'], zh: ['市场匹配', '根据公开信息，按你的预算和目标对期房市场排序。'], ar: ['السوق المناسب', 'رتّب أسواق الشراء على الخارطة بالمعلومات العامة حسب ميزانيتك وأهدافك.'] },
  '/tools/deposit-protection/': { es: ['Protección del depósito', 'Lo que ofrecen la ley y los registros oficiales en cada mercado.'], de: ['Schutz der Anzahlung', 'Was Gesetz und amtliche Register in jedem Markt bieten.'], fr: ['Protection de l’acompte', 'Ce que la loi et les registres officiels offrent sur chaque marché.'], nl: ['Bescherming van de aanbetaling', 'Wat de wet en officiële registers in elke markt bieden.'], ru: ['Защита задатка', 'Что дают закон и официальные реестры на каждом рынке.'], zh: ['定金保护查询', '各市场法律和官方登记提供的保护。'], ar: ['حماية الدفعة المقدمة', 'ما يوفّره القانون والسجلات الرسمية في كل سوق.'] },
  '/tools/insolvency-check/': { es: ['Comprobación de insolvencia', 'Escribe el nombre legal de la empresa promotora y ve los avisos oficiales de insolvencia (UK Gazette, BORME de España), con enlaces.'], de: ['Insolvenzprüfung', 'Rechtlichen Namen der Bauträgerfirma eingeben und amtliche Insolvenzmeldungen sehen (UK Gazette, BORME Spanien), mit Links.'], fr: ['Vérification d’insolvabilité', 'Tapez le nom légal de la société du promoteur et voyez les avis officiels d’insolvabilité (UK Gazette, BORME en Espagne), avec liens.'], nl: ['Insolventiecontrole', 'Typ de juridische naam van het ontwikkelbedrijf en zie officiële insolventiemeldingen (UK Gazette, BORME Spanje), met links.'], ru: ['Проверка банкротства', 'Введите юридическое имя компании застройщика и увидите официальные уведомления о банкротстве (UK Gazette, BORME в Испании) со ссылками.'], zh: ['破产检查', '输入开发公司的法定名称，查看官方破产公告（英国 Gazette、西班牙 BORME），附链接。'], ar: ['فحص الإعسار', 'اكتب الاسم القانوني لشركة المطوّر واطّلع على إشعارات الإعسار الرسمية (UK Gazette وBORME في إسبانيا) مع الروابط.'] },
  '/tools/agent-check/': { es: ['¿Tiene licencia este agente?', 'Comprueba una tarjeta de bróker o una agencia de Dubái en el registro oficial, y dónde comprobarlo a mano en otros países.'], de: ['Hat dieser Makler eine Lizenz?', 'Eine Dubai-Maklerkarte oder Agentur im amtlichen Register prüfen, und wo Sie in anderen Ländern selbst prüfen.'], fr: ['Cet agent a-t-il une licence ?', 'Vérifiez une carte de courtier ou une agence de Dubaï dans le registre officiel, et où vérifier à la main dans d’autres pays.'], nl: ['Heeft deze makelaar een licentie?', 'Controleer een Dubai-makelaarskaart of kantoor in het officiële register, en waar je het in andere landen zelf nagaat.'], ru: ['Есть ли у агента лицензия?', 'Проверьте карточку брокера или агентство Дубая в официальном реестре, и где проверить вручную в других странах.'], zh: ['这个中介有执照吗？', '在官方登记中查询迪拜经纪人卡或经纪公司，以及在其他国家手动查询的途径。'], ar: ['هل هذا الوسيط مرخّص؟', 'افحص بطاقة وسيط أو شركة وساطة في دبي في السجل الرسمي، وأين تفحص يدوياً في بلدان أخرى.'] },
  '/tools/my-checklist/': { es: ['Tu lista personal', 'Qué comprobar antes de firmar, antes de cada pago y antes de la entrega.'], de: ['Ihre persönliche Checkliste', 'Was vor der Unterschrift, vor jeder Zahlung und vor der Übergabe zu prüfen ist.'], fr: ['Votre liste personnelle', 'Ce qu’il faut vérifier avant de signer, avant chaque paiement et avant la livraison.'], nl: ['Je persoonlijke checklist', 'Wat te controleren voor je tekent, voor elke betaling en voor de oplevering.'], ru: ['Ваш личный чек-лист', 'Что проверить до подписи, перед каждым платежом и перед сдачей.'], zh: ['你的个人清单', '签约前、每次付款前和交付前要检查的事项。'], ar: ['قائمتك الشخصية', 'ما تفحصه قبل التوقيع وقبل كل دفعة وقبل التسليم.'] },
  '/tools/refund-tracker/': { es: ['Seguimiento de reembolsos y reclamaciones', 'Apunta cada contacto, plazo y pago; se guarda solo en tu navegador.'], de: ['Erstattungs- und Anspruchs-Tracker', 'Jeden Kontakt, jede Frist und Zahlung notieren; nur in Ihrem Browser gespeichert.'], fr: ['Suivi des remboursements et réclamations', 'Notez chaque contact, délai et paiement ; enregistré seulement dans votre navigateur.'], nl: ['Tracker voor terugbetaling en claims', 'Noteer elk contact, elke termijn en betaling; alleen in je browser opgeslagen.'], ru: ['Учёт возвратов и претензий', 'Записывайте каждый контакт, срок и платёж; хранится только в вашем браузере.'], zh: ['退款与索赔跟踪', '记录每次联系、期限和付款；只保存在你的浏览器中。'], ar: ['متتبّع الاسترداد والمطالبات', 'سجّل كل تواصل وموعد ودفعة؛ يُحفظ في متصفحك فقط.'] },
  '/visit/': { es: ['App de visita a obra', 'Lista, fotos con GPS y hora, cada entrada encadenada en tu móvil, exportada como JSON firmado y PDF. No se sube nada.'], de: ['App für Baustellenbesuche', 'Checkliste, Fotos mit GPS und Zeit, jeder Eintrag auf Ihrem Handy verkettet, als signiertes JSON und PDF exportiert. Nichts wird hochgeladen.'], fr: ['Appli de visite de chantier', 'Liste, photos avec GPS et heure, chaque entrée chaînée sur votre téléphone, exportée en JSON signé et PDF. Rien n’est envoyé.'], nl: ['App voor bouwplaatsbezoek', 'Checklist, foto’s met gps en tijd, elk item op je telefoon geketend, geëxporteerd als ondertekende json en pdf. Er wordt niets geüpload.'], ru: ['Приложение для визита на стройку', 'Чек-лист, фото с GPS и временем, каждая запись в цепочке на телефоне, экспорт в подписанный JSON и PDF. Ничего не загружается.'], zh: ['工地访问应用', '清单、带 GPS 和时间的照片，每条记录在手机上链式保存，导出为签名 JSON 和 PDF。不上传任何内容。'], ar: ['تطبيق زيارة الموقع', 'قائمة تحقق وصور بالموقع والوقت، كل إدخال مسلسل على هاتفك، ويُصدَّر بصيغة JSON موقّعة وPDF. لا يُرفع شيء.'] },
  '/buyer-reports/': { es: ['Informes firmados de compradores', '¿Compraste en un proyecto seguido? Informa de retrasos, problemas de pago o una buena experiencia, firmado con una passkey.'], de: ['Signierte Käuferberichte', 'In ein verfolgtes Projekt gekauft? Verzögerungen, Zahlungsprobleme oder gute Erfahrungen melden, mit Passkey signiert.'], fr: ['Témoignages signés d’acheteurs', 'Vous avez acheté dans un projet suivi ? Signalez retards, problèmes de paiement ou une bonne expérience, signé avec une passkey.'], nl: ['Ondertekende koperverslagen', 'Gekocht in een gevolgd project? Meld vertragingen, betaalproblemen of een goede ervaring, ondertekend met een passkey.'], ru: ['Подписанные отчёты покупателей', 'Купили в отслеживаемом проекте? Сообщите о задержках, проблемах с оплатой или хорошем опыте, с подписью passkey.'], zh: ['签名买家报告', '买了我们跟踪的项目？用 passkey 签名，报告延期、付款问题或良好体验。'], ar: ['تقارير المشترين الموقّعة', 'اشتريت في مشروع نتابعه؟ أبلغ عن التأخير أو مشاكل الدفع أو تجربة جيدة، موقّعة بمفتاح مرور.'] }
};

